-- Generated by `engine types sync` from types/*.toml (sqlite).
-- create type `update`

CREATE TABLE content_update (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    slug TEXT NOT NULL UNIQUE CHECK (length(slug) BETWEEN 1 AND 80 AND slug NOT GLOB '*[^a-z0-9-]*' AND slug NOT GLOB '-*' AND slug NOT GLOB '*-' AND slug NOT GLOB '*--*'),
    status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published')),
    version INTEGER NOT NULL DEFAULT 1,
    created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    published_at TEXT,
    "title" TEXT,
    "body" TEXT
);
CREATE TRIGGER content_update_changes_insert AFTER INSERT ON content_update BEGIN
    INSERT INTO engine_changes (content_type, item_id, op) VALUES ('update', NEW.id, 'INSERT');
END;
CREATE TRIGGER content_update_changes_update AFTER UPDATE ON content_update BEGIN
    INSERT INTO engine_changes (content_type, item_id, op) VALUES ('update', NEW.id, 'UPDATE');
END;
CREATE TRIGGER content_update_changes_delete AFTER DELETE ON content_update BEGIN
    INSERT INTO engine_changes (content_type, item_id, op) VALUES ('update', OLD.id, 'DELETE');
END;
